// Validate and normalise a lead. Rejects incomplete records
// instead of forwarding garbage into the CRM.
//
// Returns one item per input with `ok` set. The If node downstream splits
// accepted from rejected, so a bad email never reaches Sheets or HubSpot.

const results = [];

for (const item of $input.all()) {
  // Webhook delivers the POST body under `body`; guard for direct/manual runs.
  const p = item.json.body || item.json || {};

  const rawEmail = (p.email || '').trim();
  const emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(rawEmail);
  const name = (p.name || '').trim();
  const message = (p.message || '').trim();

  const reasons = [];
  if (!emailOk) reasons.push('invalid email');
  if (!name)       reasons.push('missing name');
  if (!message)    reasons.push('missing message');

  const parts = name.split(/\s+/);

  results.push({
    json: {
      ok: reasons.length === 0,
      reject_reason: reasons.length ? reasons.join(', ') : null,
      email: rawEmail.toLowerCase(),
      firstname: parts[0] || '',
      // Everything after the first token is the surname, so
      // "Ada Byron King" does not become lastname="Byron".
      lastname: parts.slice(1).join(' ') || '',
      // Bound the free-text field so a pasted document cannot bloat the sheet.
      message: message.slice(0, 500),
      submitted_at: new Date().toISOString(),
      lead_source: 'form'
    }
  });
}

return results;

// Rejection sink. Rejected records are logged rather than silently
// dropped so a form break is visible instead of invisible.

const rejected = $input.all()
  .map(i => i.json.reject_reason || 'unknown')
  .reduce((acc, r) => {
    acc[r] = (acc[r] || 0) + 1;
    return acc;
  }, {});

console.log('REJECTED LEADS:', JSON.stringify(rejected));

return $input.all().map(i => ({
  json: {
    rejected: true,
    reason: i.json.reject_reason,
    email_attempted: i.json.email
  }
}));
